<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Amendment to Registration Statement</title>
    <style>
        body {
            font-family: "Times New Roman", Times, serif;
            font-size: 15px;
            line-height: 1.3;
            margin: 0;
            padding: 40px;
            background-color: #f4f4f4;
            display: flex;
            justify-content: center;
        }
        .document-container {
            background-color: white;
            width: 8.5in;
            min-height: 11in;
            padding: 0.6in 0.5in;
            box-sizing: border-box;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
            color: black;
        }
        .typewriter {
            font-family: "Courier New", Courier, monospace;
            font-size: 16px;
            font-weight: bold;
            letter-spacing: 0.5px;
        }
        .header-top {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 5px;
        }
        .header-left {
            font-weight: bold;
            font-size: 16px;
        }
        .header-right {
            text-align: right;
            line-height: 1.2;
            max-width: 500px;
        }
        .header-right-top {
            display: flex;
            justify-content: flex-end;
            align-items: center;
            gap: 15px;
            margin-bottom: 5px;
        }
        .header-title {
            font-weight: bold;
            font-size: 17px;
        }
        .omb-box {
            font-size: 10px;
            text-align: left;
            line-height: 1.1;
        }
        .header-subtitle {
            font-weight: bold;
            font-style: italic;
            font-size: 15px;
        }
        .thick-separator {
            border-bottom: 7px solid #111;
            margin-top: 5px;
            margin-bottom: 25px;
        }
        .thin-separator {
            border-bottom: 1px solid #111;
            margin: 20px 0 15px 0;
        }
        .section-box {
            border-top: 1px solid #111;
            border-bottom: 1px solid #111;
            display: flex;
            align-items: stretch;
            margin-bottom: 20px;
        }
        .box-col-1 {
            flex: 1.2;
            border-right: 1px solid #111;
            padding: 5px 0;
        }
        .box-col-2 {
            flex: 1;
            padding: 5px 0;
        }
        .box-label {
            padding-left: 5px;
            margin-bottom: 15px;
        }
        .checkbox-row {
            display: flex;
            align-items: flex-start;
            margin-bottom: 10px;
        }
        .checkbox-icon {
            font-size: 18px;
            line-height: 1;
            margin-right: 8px;
        }
        .data-grid {
            display: grid;
            grid-template-columns: 280px 120px;
            row-gap: 2px;
            margin-left: 20px;
        }
        .footer {
            display: flex;
            justify-content: center;
            position: relative;
            margin-top: 60px;
            font-size: 11px;
            font-weight: bold;
        }
        .footer-right {
            position: absolute;
            right: 0;
            text-align: right;
            line-height: 1.2;
        }
    </style>
</head>
<body>

<div class="document-container">

    <!-- Header -->
    <div class="header-top">
        <div class="header-left">
            U.S. Department of Justice<br>
            Washington, DC 20530
        </div>
        <div class="header-right">
            <div class="header-right-top">
                <div class="header-title">Amendment to Registration Statement</div>
                <div class="omb-box">
                    <b>OMB No. 1105-0004</b><br>
                    Approval Expires Oct. 31, 1983
                </div>
            </div>
            <div class="header-subtitle">
                Pursuant to the Foreign Agents Registration Act of 1938, as amended
            </div>
        </div>
    </div>

    <div class="thick-separator"></div>

    <!-- Section 1 & 2 -->
    <div class="section-box">
        <div class="box-col-1">
            <div class="box-label">1. Name of Registrant</div>
            <div class="typewriter" style="text-align: center; margin-bottom: 10px;">BRITISH VIRGIN ISLANDS TOURIST BOARD</div>
        </div>
        <div class="box-col-2">
            <div class="box-label">2. Registration No.</div>
            <div class="typewriter" style="text-align: center; margin-bottom: 10px;">3354</div>
        </div>
    </div>

    <!-- Section 3 -->
    <div style="margin-bottom: 15px;">3. This amendment is filed to accomplish the following indicated purpose or purposes:</div>

    <div style="display: flex; margin-top: 15px;">
        <div style="flex: 1;">
            <div class="checkbox-row">
                <span class="checkbox-icon">&#9744;</span>
                <span>To correct a deficiency in</span>
            </div>
            <div class="checkbox-row" style="margin-left: 25px;">
                <span class="checkbox-icon">&#9744;</span>
                <span>Initial Statement</span>
            </div>
            <div class="checkbox-row" style="margin-left: 25px;">
                <span class="checkbox-icon">&#9746;</span>
                <span>Supplemental Statement for <span class="typewriter" style="border-bottom: 1px solid black; padding: 0 15px;">Item 15A</span></span>
            </div>
        </div>
        <div style="flex: 1.1;">
            <div class="checkbox-row" style="margin-bottom: 15px;">
                <span class="checkbox-icon">&#9744;</span>
                <span>To give a 10-day notice of a change in information as required by Section 2(b) of the Act.</span>
            </div>
            <div class="checkbox-row">
                <span class="checkbox-icon">&#9744;</span>
                <span>Other purpose (specify) <span style="border-bottom: 1px solid black; display: inline-block; width: 200px;"></span></span>
            </div>
        </div>
    </div>

    <div class="checkbox-row" style="margin-top: 15px;">
        <span class="checkbox-icon">&#9744;</span>
        <span>To give notice of change in an exhibit previously filed.</span>
    </div>

    <div class="thin-separator"></div>

    <!-- Section 4 -->
    <div>4. If this amendment requires the filing of a document or documents, please list-</div>
    <div class="typewriter" style="margin-left: 20px; margin-top: 20px; margin-bottom: 10px;">
        Disbursements for office operations as of April 30, 1984
    </div>

    <div class="thin-separator"></div>

    <!-- Section 5 -->
    <div style="margin-bottom: 25px; text-align: justify;">
        5. Each item checked above must be explained below in full detail together with, where appropriate, specific reference to and identity of the item in the registration statement to which it pertains. If more space is needed, full size insert sheets may be used.
    </div>

    <div style="display: flex; margin-top: 20px; position: relative;">
        <!-- Data Table -->
        <div class="typewriter data-grid">
            <div>Telephone</div><div style="text-align: right;">3,012.23</div>
            <div>Rent</div><div style="text-align: right;">5,406.57</div>
            <div>Office equipment</div><div style="text-align: right;">453.28</div>
            <div>Office Supplies</div><div style="text-align: right;">926.86</div>
            <div>Postage</div><div style="text-align: right;">2,500.00</div>
            <div>Subscriptions</div><div style="text-align: right;">263.28</div>
            <div>Travel Allowances</div><div style="text-align: right;">3,061.42</div>
            <div>Freight</div><div style="text-align: right;">3,340.51</div>
            <div>Telex</div><div style="text-align: right;">229.21</div>
            <div>Salaries</div><div style="text-align: right;">16,138.00</div>
            <div>Clipping Service</div><div style="text-align: right;">822.21</div>
            <div>Sales Retainer Fees</div><div style="text-align: right;">1,400.00</div>
            <div>Prepaid Advertising</div><div style="text-align: right;">(15,000.00)</div>
            <div>Messenger/Couriers</div><div style="text-align: right;">110.25</div>
            <div>Tradeshows/Expositions</div><div style="text-align: right;">5,854.31</div>
            <div>Miscellaneous</div><div style="text-align: right; border-bottom: 1px solid black; padding-bottom: 2px;">5,395.79</div>
        </div>

        <!-- Total Box -->
        <div class="typewriter" style="position: absolute; bottom: 0; left: 450px;">
            <span style="border-bottom: 1.5px solid black; padding-bottom: 2px;">Total: &nbsp;&nbsp;$33,913.92</span>
        </div>
    </div>

    <!-- Footer -->
    <div class="footer">
        <span>Formerly OBD-68</span>
        <div class="footer-right">
            FORM CRM-158<br>
            AUG. 82
        </div>
    </div>

</div>

</body>
</html>
